@mcp.tool()
def memory_metrics() -> dict:
    """Inspect memory pipeline/retrieval/consolidation row counts."""
    return memory_tools.memory_metrics()

def ingest_hook_payload(self, payload: dict, default_agent: str='codex', *, process: bool=True) -> dict[str, object]:
    normalized = self.normalize_event_payload(payload, default_agent=default_agent)
    if normalized is None:
        return {'event_id': None, 'session_id': payload.get('session_id') or 'default', 'skipped': True}
    if not self.session_exists(normalized['session_id']):
        self.create_session(normalized['session_id'], normalized['session_id'])
    event = self.add_event(session_id=normalized['session_id'], agent=normalized['agent'], event_type=normalized['event_type'], content=normalized['content'], metadata=normalized['metadata'], created_at=normalized.get('created_at'), source_app=normalized['source_app'], process=process)
    if process and event.event_type.lower() in {'stop', 'session_stop'}:
        self.generate_session_summary(event.session_id)
    return {'event_id': event.id, 'session_id': event.session_id}

@mcp.tool()
def memory_import(in_path: str) -> dict:
    """Import a JSONL memory snapshot into the local SQLite store."""
    return memory_tools.memory_import(in_path=in_path)

def memory_export(self, *, out_path: str='', session_id: str='') -> dict[str, Any]:
    target = Path(out_path) if out_path else self.settings.export_dir / 'memory_snapshot.jsonl'
    rows = self.memory.export_snapshot(out_path=target, session_id=session_id or None)
    return {'ok': True, 'rows': rows, 'out_path': str(target.resolve())}

def _memory_fingerprint(row: sqlite3.Row) -> str:
    summary = str(row['summary'] or '')
    summary = re.sub('^(decision|fix|bug|validation|reference|observation|file change)\\s*(\\[[^\\]]+\\])?:\\s*', '', summary, flags=re.I)
    text = ' '.join([str(row['memory_type'] or ''), str(row['topic_key'] or ''), summary])
    return re.sub('[^a-z0-9]+', ' ', text.lower()).strip()
